import{_ as l,a0 as d,w as o,s as r,I as e,x as a,a1 as i,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"把你的樹莓派家庭實驗室變成一個網絡文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"把你的樹莓派家庭實驗室變成一個網絡文件系統 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"把你的樹莓派家庭實驗室變成一個網絡文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"把你的樹莓派家庭實驗室變成一個網絡文件系統 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200522 Turn your Raspberry Pi homelab into a network filesystem","title":"把你的樹莓派家庭實驗室變成一個網絡文件系統","tag":"202007","desc":""},"relativePath":"202007/20200522 Turn your Raspberry Pi homelab into a network filesystem.md","filePath":"[post].md"}'),c={name:"202007/20200522 Turn your Raspberry Pi homelab into a network filesystem.md"};function h(b,s,u,g,k,f){const n=d("Link");return o(),r("div",null,[s[26]||(s[26]=e("h1",{id:"把你的樹莓派家庭實驗室變成一個網絡文件系統",tabindex:"-1"},[a("把你的樹莓派家庭實驗室變成一個網絡文件系統 "),e("a",{class:"header-anchor",href:"#把你的樹莓派家庭實驗室變成一個網絡文件系統","aria-label":"Permalink to “把你的樹莓派家庭實驗室變成一個網絡文件系統”"},"​")],-1)),s[27]||(s[27]=e("blockquote",null,[e("p",null,"使用 NFS 服務器將共享文件系統添加到你的家庭實驗室。")],-1)),s[28]||(s[28]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202007/14/154349bgrgrwzexluuvzev.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("共享文件系統是為家庭實驗室增加通用性和功能性的好方法。在實驗室中為客户端共享一個集中的文件系統，使得組織數據、進行備份和共享數據變得相當容易。這對於在多個服務器上進行負載均衡的 Web 應用和 ",-1)),i(n,{href:"https://opensource.com/resources/what-is-kubernetes"},{default:p(()=>[...s[0]||(s[0]=[a("Kubernetes",-1)])]),_:1}),s[2]||(s[2]=a(" 使用的持久化捲來説，尤其有用，因為它允許在任何數量的節點上用持久化數據來輪轉 Pod。",-1))]),s[29]||(s[29]=e("p",null,"無論你的家庭實驗室是由普通計算機、多餘的企業服務器，還是樹莓派或其他單板計算機（SBC）組成，共享文件系統都是一種有用的資產，而網絡文件系統（NFS）服務器是創建共享文件系統的好方法。",-1)),e("p",null,[s[4]||(s[4]=a("我之前寫過關於",-1)),i(n,{href:"https://linux.cn/article-12277-1.html"},{default:p(()=>[...s[3]||(s[3]=[a("建立“家庭私有云”",-1)])]),_:1}),s[5]||(s[5]=a("的文章，這是一個由樹莓派或其他 SBC 組成的家庭實驗室，也許還有其他一些消費類硬件或台式 PC。NFS 服務器是這些組件之間共享數據的理想方式。由於大多數 SBC 的操作系統是通過 SD 卡運行的，所以存在一些挑戰。尤其是在用作計算機的操作系統磁盤時，SD 卡的故障率會增加，它們並不是用來不斷地讀寫的。你實際需要的是一個真正的硬盤：它們通常比 SD 卡的每 GB 價格便宜，特別是對於較大的磁盤，而且它們不太可能持續發生故障。樹莓派 4 現在帶有 USB 3.0 接口，而 USB 3.0 硬盤無處不在，價格也很實惠。這是一個完美的搭配。在這個項目中，我將使用一個 2TB 的 USB 3.0 外置硬盤插入到運行 NFS 服務器的樹莓派 4 中。",-1))]),s[30]||(s[30]=t(`<p><img src="https://opensource.com/sites/default/files/uploads/raspberrypi_with_hard-disk.jpg" alt="Raspberry Pi with a USB hard disk" title="Raspberry Pi with a USB hard disk"></p><h3 id="安裝-nfs-服務器軟件" tabindex="-1">安裝 NFS 服務器軟件 <a class="header-anchor" href="#安裝-nfs-服務器軟件" aria-label="Permalink to “安裝 NFS 服務器軟件”">​</a></h3><p>我在樹莓派上運行 Fedora 服務器，但這個項目也可以在其他發行版上運行。要在 Fedora 上運行 NFS 服務器，你需要 <code>nfs-utils</code> 包，幸運的是它已經安裝好了（至少在 Fedora 31 中是這樣）。如果你打算運行 NFSv3 服務，你還需要 <code>rpcbind</code> 包，但它不是 NFSv4 的嚴格要求。</p><p>如果你的系統中還沒有這些軟件包，請使用 <code>dnf</code> 命令安裝它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 安裝 nfs-utils 和 rpcbind</span></span>
<span class="line"><span>$ sudo dnf install nfs-utils rpcbind</span></span></code></pre></div><p>Raspbian 是另一個與樹莓派一起使用的流行操作系統，設置幾乎完全相同。軟件包名稱不同而已，但這是唯一的主要區別。要在運行 Raspbian 的系統上安裝 NFS 服務器，你需要以下軟件包。</p><ul><li><code>nfs-common</code>：這些文件是 NFS 服務器和客户端的通用文件。</li><li><code>nfs-kernel-server</code>：主要的 NFS 服務器軟件包。</li></ul><p>Raspbian 使用 <code>apt-get</code> 來管理軟件包（而不是像 Fedora 那樣使用 <code>dnf</code>），所以用它來安裝軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 對於 Raspbian 系統，使用 apt-get 來安裝 NFS 軟件包</span></span>
<span class="line"><span>$ sudo apt-get install nfs-common nfs-kernel-server</span></span></code></pre></div><h3 id="準備一個-usb-硬盤作為存儲設備" tabindex="-1">準備一個 USB 硬盤作為存儲設備 <a class="header-anchor" href="#準備一個-usb-硬盤作為存儲設備" aria-label="Permalink to “準備一個 USB 硬盤作為存儲設備”">​</a></h3><p>正如我上面提到的，USB 硬盤是為樹莓派或其他 SBC 提供存儲的好選擇，尤其是用於操作系統磁盤鏡像的 SD 卡並不適合這個用途。對於家庭私有云，你可以使用廉價的 USB 3.0 硬盤進行大規模存儲。插入磁盤，使用 <code>fdisk</code> 找出分配給它的設備 ID，就可以使用它工作了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 使用 fdisk 找到你的硬盤</span></span>
<span class="line"><span># 無關的硬盤信息已經省略</span></span>
<span class="line"><span>$ sudo fdisk -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 1.84 TiB, 2000398933504 bytes, 3907029167 sectors</span></span>
<span class="line"><span>Disk model: BUP Slim BK</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0xe3345ae9</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors  Size Id Type</span></span>
<span class="line"><span>/dev/sda1        2048 3907028991 3907026944  1.8T 83 Linux</span></span></code></pre></div><p>為了清楚起見，在上面的例子輸出中，除了我感興趣的那個磁盤，我省略了所有其它磁盤的信息。你可以看到我想使用的 USB 磁盤被分配了設備 <code>/dev/sda</code>，你可以看到一些關於型號的信息（<code>Disk model: BUP Slim BK</code>），這有助於我識別正確的磁盤。該磁盤已經有了一個分區，它的大小也證實了它就是我要找的磁盤。</p><p>注意：請確保正確識別你的設備的磁盤和分區。它可能與上面的例子不同。</p><p>在驅動器上創建的每個分區都有一個特殊的通用唯一標識符（UUID）。計算機使用 UUID 來確保它使用 <code>/etc/fstab</code> 配置文件將正確的分區掛載到正確的位置。你可以使用 <code>blkid</code> 命令檢索分區的 UUID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 獲取該分區的塊設備屬性</span></span>
<span class="line"><span># 確保你使用了合適的分區，它應該有所不同。</span></span>
<span class="line"><span>$ sudo blkid /dev/sda1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda1: LABEL=&quot;backup&quot; UUID=&quot;bd44867c-447c-4f85-8dbf-dc6b9bc65c91&quot; TYPE=&quot;xfs&quot; PARTUUID=&quot;e3345ae9-01&quot;</span></span></code></pre></div><p>在這裏，<code>/dev/sda1</code> 的 UUID 是 <code>bd44867c-447c-4f85-8dbf-dc6b9bc65c91</code>。你的 UUID 會有所不同，所以要記下來。</p><h3 id="配置樹莓派在啓動時掛載這個磁盤-然後掛載它" tabindex="-1">配置樹莓派在啓動時掛載這個磁盤，然後掛載它 <a class="header-anchor" href="#配置樹莓派在啓動時掛載這個磁盤-然後掛載它" aria-label="Permalink to “配置樹莓派在啓動時掛載這個磁盤，然後掛載它”">​</a></h3><p>現在你已經確定了要使用的磁盤和分區，你需要告訴計算機如何掛載它，每次啓動時都要這樣做。現在就去掛載它。因為這是一個 USB 磁盤，可能會被拔掉，所以你還要配置樹莓派在啓動時如果磁盤沒有插入或有其它不可用情況時不要等待。</p><p>在 Linux 中，通過將分區添加到 <code>/etc/fstab</code> 配置文件中，包括你希望它被掛載的位置和一些參數來告訴計算機如何處理它。這個例子將把分區掛載到 <code>/srv/nfs</code>，所以先創建這個路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 創建該磁盤分區的掛載點</span></span>
<span class="line"><span>$ sudo mkdir -p /srv/nfs</span></span></code></pre></div><p>接下來，使用以下語法格式修改 <code>/etc/fstab</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;disk id&gt;     &lt;mountpoint&gt;      &lt;filesystem type&gt;     &lt;options&gt;     &lt;fs_freq&gt; &lt;fs_passno&gt;</span></span></code></pre></div><p>使用你之前確定的 UUID 作為磁盤 ID。正如我在上一步提到的，掛載點是 <code>/srv/nfs</code>。對於文件系統類型，通常最好選擇其實際的文件系統，但是因為這是一個 USB 磁盤，所以使用 <code>auto</code>。</p><p>對於選項值，使用 <code>nosuid,nodev,nofail</code>。</p><h4 id="關於手冊頁的一個旁白" tabindex="-1">關於手冊頁的一個旁白 <a class="header-anchor" href="#關於手冊頁的一個旁白" aria-label="Permalink to “關於手冊頁的一個旁白”">​</a></h4><p>其實，有<em>很多</em>可能的選項，手冊頁（<code>man</code>）是查看它們的最好方法。查看 <code>fstab</code> 的手冊頁是一個很好的開始。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 打開 fstab 的手冊頁</span></span>
<span class="line"><span>$ man fstab</span></span></code></pre></div><p>這將打開與 <code>fstab</code> 命令相關的手冊/文檔。在手冊頁中，每個選項都被分解成了不同的內容，以顯示它的作用和常用的選擇。例如，“第四個字段（fs_mntopts）”給出了該字段中可用選項的一些基本信息，並引導你到 <code>man 8 mount</code> 中獲取 <code>mount</code> 選項更深入的描述。這是有道理的，因為 <code>/etc/fstab</code> 文件，本質上是告訴計算機如何自動掛載磁盤，就像你手動使用 <code>mount</code> 命令一樣。</p><p>你可以從 <code>mount</code> 的手冊頁中獲得更多關於你將使用的選項的信息。數字 8 表示手冊頁的章節。在這裏，第 8 章節是<em>系統管理工具和守護進程</em>。</p><p>你可以從 <code>man</code> 的手冊頁中得到標準章節的列表。</p><p>回到掛載磁盤，讓我們看看 <code>man 8 mount</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 打開第 8 章節的 mount 手冊頁</span></span>
<span class="line"><span>$ man 8 mount</span></span></code></pre></div><p>在這個手冊頁中，你可以查看上面列出的選項的作用。</p><ul><li><code>nosuid</code>：不理會 suid/guid 位。不允許放在 U 盤上的任何文件以 root 身份執行。這是一個良好的安全實踐。</li><li><code>nodev</code>：不識別文件系統中的字符或塊特殊設備，即不理會在 U 盤上的任何設備節點。另一個良好的安全實踐。</li><li><code>nofail</code>：如果設備不存在，不要記錄任何錯誤。這是一個 U 盤，可能沒有插入，所以在這種情況下，它將被忽略。</li></ul><p>回到你正在添加到 <code>/etc/fstab</code> 文件的那一行，最後還有兩個選項：<code>fs_freq</code> 和 <code>fs_passno</code>。它們的值與一些過時的選項有關，<em>大多數</em>現代系統對這兩個選項都只用 <code>0</code>，特別是對 USB 磁盤上的文件系統而言。<code>fs_freq</code> 的值與 <code>dump</code> 命令和文件系統的轉儲有關。<code>fs_passno</code> 的值定義了啓動時要 <code>fsck</code> 的文件系統及其順序，如果設置了這個值，通常根分區是 <code>1</code>，其他文件系統是 <code>2</code>，將該值設置為 <code>0</code> 以跳過在該分區上使用 <code>fsck</code>。</p><p>在你喜歡的編輯器中，打開 <code>/etc/fstab</code> 文件，添加 U 盤上分區的條目，將這裏的值替換成前面步驟中得到的值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># With sudo, or as root, add the partition info to the /etc/fstab file</span></span>
<span class="line"><span>UUID=&quot;bd44867c-447c-4f85-8dbf-dc6b9bc65c91&quot;    /srv/nfs    auto    nosuid,nodev,nofail,noatime 0 0</span></span></code></pre></div><h3 id="啓用並啓動-nfs-服務器" tabindex="-1">啓用並啓動 NFS 服務器 <a class="header-anchor" href="#啓用並啓動-nfs-服務器" aria-label="Permalink to “啓用並啓動 NFS 服務器”">​</a></h3><p>安裝好軟件包，並將分區添加到你的 <code>/etc/fstab</code> 文件中，現在你可以開始啓動 NFS 服務器了。在 Fedora 系統中，你需要啓用和啓動兩個服務：<code>rpcbind</code> 和 <code>nfs-server</code>。使用 <code>systemctl</code> 命令來完成這項工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 啓動 NFS 服務器和 rpcbind</span></span>
<span class="line"><span>$ sudo systemctl enable rpcbind.service</span></span>
<span class="line"><span>$ sudo systemctl enable nfs-server.service</span></span>
<span class="line"><span>$ sudo systemctl start rpcbind.service</span></span>
<span class="line"><span>$ sudo systemctl start nfs-server.service</span></span></code></pre></div><p>在 Raspbian 或其他基於 Debian 的發行版上，你只需要使用 <code>systemctl</code> 命令啓用並啓動 <code>nfs-kernel-server</code> 服務即可，方法同上。</p><h4 id="rpcbind" tabindex="-1">RPCBind <a class="header-anchor" href="#rpcbind" aria-label="Permalink to “RPCBind”">​</a></h4><p>rpcbind 工具用於將遠程過程調用（RPC）服務映射到其監聽的端口。根據 rpcbind 手冊頁：</p><blockquote><p>“當一個 RPC 服務啓動時，它會告訴 rpcbind 它正在監聽的地址，以及它準備服務的 RPC 程序號。當客户機想對給定的程序號進行 RPC 調用時，它首先與服務器機器上的 rpcbind 聯繫，以確定 RPC 請求應該發送到哪裏的地址。”</p></blockquote><p>在 NFS 服務器這個案例中，rpcbind 會將 NFS 的協議號映射到 NFS 服務器監聽的端口上。但是，NFSv4 不需要使用 rpcbind。如果你<em>只</em>使用 NFSv4 （通過從配置中刪除版本 2 和版本 3），則不需要使用 rpcbind。我把它放在這裏是為了向後兼容 NFSv3。</p><h3 id="導出掛載的文件系統" tabindex="-1">導出掛載的文件系統 <a class="header-anchor" href="#導出掛載的文件系統" aria-label="Permalink to “導出掛載的文件系統”">​</a></h3><p>NFS 服務器根據另一個配置文件 <code>/etc/exports</code> 來決定與哪些遠程客户端共享（導出）哪些文件系統。這個文件只是一個 IP（或子網）與要共享的文件系統的映射，以及一些選項（只讀或讀寫、root 去除等）。該文件的格式是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;目錄&gt;     &lt;主機&gt;(選項)</span></span></code></pre></div><p>在這個例子中，你將導出掛載到 <code>/srv/nfs</code> 的分區。這是“目錄”部分。</p><p>第二部分，主機，包括你要導出這個分區的主機。這些主機可以是單個主機：使用具有完全限定域名（FQDN）或主機名、主機的 IP 地址來指定；也可以是一組主機：使用通配符字符來匹配域（如 *.example.org）、IP 網絡（如無類域間路由 CIDR 標識）或網組表示。</p><p>第三部分包括應用於該導出的選項。</p><ul><li><code>ro/rw</code>：將文件系統導出為只讀或讀寫。</li><li><code>wdelay</code>：如果即將進行另一次寫入，則推遲對磁盤的寫入，以提高性能（如果你使用的是固態 USB 磁盤，這<em>可能</em>沒有那麼有用）</li><li><code>root_squash</code>：防止客户機上的任何 root 用户在主機上有 root 權限，並將 root UID 設置為 <code>nfsnobody</code> 作為安全防範措施。</li></ul><p>測試導出你掛載在 <code>/srv/nfs</code> 處的分區到一個客户端 —— 例如，一台筆記本電腦。確定你的客户機的 IP 地址（我的筆記本是 <code>192.168.2.64</code>，但你的可能會不同）。你可以把它共享到一個大的子網，但為了測試，請限制在單個 IP 地址上。這個 IP 的 CIDR 標識是 <code>192.168.2.64/32</code>，<code>/32</code> 子網代表一個 IP。</p><p>使用你喜歡的編輯器編輯 <code>/etc/exports</code> 文件，寫上你的目錄、主機 CIDR 以及 <code>rw</code> 和 <code>root_squash</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 像這樣編輯你的 /etc/exports 文件，替換為你的系統上的信息</span></span>
<span class="line"><span>/srv/nfs    192.168.2.64/32(rw,root_squash)</span></span></code></pre></div><p>注：如果你從另一個地方複製了 <code>/etc/exports</code> 文件，或者用副本覆蓋了原文件，你可能需要恢復該文件的 SELinux 上下文。你可以使用 <code>restorecon</code> 命令來恢復。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 恢復 /etc/exports 文件的 SELinux 上下文</span></span>
<span class="line"><span>$ sudo restorecon /etc/exports</span></span></code></pre></div><p>完成後，重新啓動 NFS 服務器，以接收對 <code>/etc/exports</code> 文件的更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 重新啓動 NFS 服務器</span></span>
<span class="line"><span>$ sudo systemctl restart nfs-server.service</span></span></code></pre></div><h3 id="給-nfs-服務打開防火牆" tabindex="-1">給 NFS 服務打開防火牆 <a class="header-anchor" href="#給-nfs-服務打開防火牆" aria-label="Permalink to “給 NFS 服務打開防火牆”">​</a></h3>`,61)),e("p",null,[s[7]||(s[7]=a("有些系統，默認不運行",-1)),i(n,{href:"https://opensource.com/article/18/9/linux-iptables-firewalld"},{default:p(()=>[...s[6]||(s[6]=[a("防火牆服務",-1)])]),_:1}),s[8]||(s[8]=a("。比如 Raspbian，默認是開放 iptables 規則，不同服務打開的端口在機器外部立即就可以使用。相比之下，Fedora 服務器默認運行的是 firewalld 服務，所以你必須為 NFS 服務器（以及 rpcbind，如果你將使用 NFSv3）打開端口。你可以通過 ",-1)),s[9]||(s[9]=e("code",null,"firewall-cmd",-1)),s[10]||(s[10]=a(" 命令來實現。",-1))]),s[31]||(s[31]=t(`<p>檢查 firewalld 使用的區域並獲取默認區域。對於 Fedora 服務器，這是 <code>FedoraServer</code> 區域。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 列出區域</span></span>
<span class="line"><span># 出於簡潔省略了部分輸出</span></span>
<span class="line"><span>$ sudo firewall-cmd --list-all-zones</span></span>
<span class="line"><span></span></span>
<span class="line"><span># R獲取默認區域信息</span></span>
<span class="line"><span># 記下默認區域</span></span>
<span class="line"><span>$ sudo firewall-cmd --get-default-zone</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 永久加入 nfs 服務到允許端口列表</span></span>
<span class="line"><span>$ sudo firewall-cmd --add-service=nfs --permanent</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 對於 NFSv3，我們需要再加一些端口： nfsv3、 rpc-mountd、 rpc-bind</span></span>
<span class="line"><span>$ sudo firewall-cmd --add-service=(nfs3,mountd,rpc-bind)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看默認區域的服務，以你的系統中使用的默認區域相應替換</span></span>
<span class="line"><span>$ sudo firewall-cmd --list-services --zone=FedoraServer</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 如果一切正常，重載 firewalld</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>就這樣，你已經成功地將 NFS 服務器與你掛載的 U 盤分區配置在一起，並將其導出到你的測試系統中進行共享。現在你可以在你添加到導出列表的系統上測試掛載它。</p><h3 id="測試-nfs-導出" tabindex="-1">測試 NFS 導出 <a class="header-anchor" href="#測試-nfs-導出" aria-label="Permalink to “測試 NFS 導出”">​</a></h3><p>首先，從 NFS 服務器上，在 <code>/srv/nfs</code> 目錄下創建一個文件來讀取。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 創建一個測試文件以共享</span></span>
<span class="line"><span>echo &quot;Can you see this?&quot; &gt;&gt; /srv/nfs/nfs_test</span></span></code></pre></div><p>現在，在你添加到導出列表中的客户端系統上，首先確保 NFS 客户端包已經安裝好。在 Fedora 系統上，它是 <code>nfs-utils</code> 包，可以用 <code>dnf</code> 安裝。Raspbian 系統有 <code>libnfs-utils</code> 包，可以用 <code>apt-get</code> 安裝。</p><p>安裝 NFS 客户端包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 用 dnf 安裝 nfs-utils 軟件包</span></span>
<span class="line"><span>$ sudo dnf install nfs-utils</span></span></code></pre></div><p>一旦安裝了客户端包，你就可以測試 NFS 的導出了。同樣在客户端，使用帶有 NFS 服務器 IP 和導出路徑的 <code>mount</code> 命令，並將其掛載到客户端的一個位置，在這個測試中是 <code>/mnt</code> 目錄。在這個例子中，我的 NFS 服務器的 IP 是 <code>192.168.2.109</code>，但你的可能會有所不同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 掛載 NFS 服務器的輸出到客户端主機</span></span>
<span class="line"><span># 確保替換為你的主機的相應信息</span></span>
<span class="line"><span>$ sudo mount 192.168.2.109:/srv/nfs /mnt</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看 nfs_test 文件是不是可見</span></span>
<span class="line"><span>$ cat /mnt/nfs_test</span></span>
<span class="line"><span>Can you see this?</span></span></code></pre></div><p>成功了！你現在已經有了一個可以工作的 NFS 服務器，可以與多個主機共享文件，允許多個讀/寫訪問，併為你的數據提供集中存儲和備份。家庭實驗室的共享存儲有很多選擇，但 NFS 是一種古老的、高效的、可以添加到你的“家庭私有云”家庭實驗室中的好選擇。本系列未來的文章將擴展如何在客户端上自動掛載 NFS 共享，以及如何將 NFS 作為 Kubernetes 持久卷的存儲類。</p><hr>`,13)),e("p",null,[s[12]||(s[12]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/20/5/nfs-raspberry-pi"},{default:p(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/20/5/nfs-raspberry-pi",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/clcollins"},{default:p(()=>[...s[13]||(s[13]=[a("Chris Collins",-1)])]),_:1}),s[18]||(s[18]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 譯者：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1}),s[20]||(s[20]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[23]||(s[23]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...s[22]||(s[22]=[a("Linux中國",-1)])]),_:1}),s[25]||(s[25]=a(" 榮譽推出",-1))])])}const S=l(c,[["render",h]]);export{v as __pageData,S as default};
